*{box-sizing:border-box} :root{--ink:#f7f6ec;--muted:#a9b5a8;--lime:#c8f05e;--deep:#13231f;--glass:rgba(17,31,29,.77)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#142522;color:var(--ink);font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:linear-gradient(180deg,#8ec9a6 0%,#bfd782 43%,#556d40 100%);isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 42%,rgba(15,27,24,.25) 100%);z-index:1}.topbar{position:absolute;left:0;right:0;top:0;height:68px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.16);z-index:4;background:linear-gradient(180deg,rgba(8,21,19,.47),transparent)}.brand{display:flex;align-items:center;gap:10px;color:white;text-decoration:none;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:1.9px}.brand-mark{font-size:27px;color:var(--lime);text-shadow:0 0 18px rgba(200,240,94,.6)}.brand-light{font-weight:500;opacity:.63;margin-left:4px}.top-center{font-size:10px;letter-spacing:2px;font-weight:800;color:#e3e7d4}.season-dot,.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#c9f45d;box-shadow:0 0 10px #c9f45d;margin-right:8px}.top-divider{color:#8e9d8b;margin:0 9px}.sound-button{background:transparent;border:1px solid rgba(255,255,255,.28);border-radius:5px;padding:9px 12px;font-size:15px;cursor:pointer}.sound-button span{font-size:9px;letter-spacing:1px;margin-left:5px;font-weight:700}.hud{position:absolute;top:85px;left:32px;right:32px;display:flex;align-items:flex-start;z-index:3;pointer-events:none}.glass{background:var(--glass);border:1px solid rgba(240,255,222,.2);box-shadow:0 14px 34px rgba(12,30,18,.2);backdrop-filter:blur(14px)}.mission-card{padding:14px 17px 13px;width:232px;border-radius:8px}.mission-eyebrow{font-size:9px;font-weight:800;letter-spacing:1.5px;color:#c9f45d}.mission-tag{float:right;padding:3px 6px;border-radius:3px;background:rgba(255,255,255,.11);color:#e4e6d9;font-size:8px;letter-spacing:1px}.mission-title{font:700 16px 'Space Grotesk',sans-serif;margin:9px 0 7px}.mission-meta{font-size:9px;letter-spacing:1px;font-weight:700;color:#b8c2b5}.meta-sep{margin:0 6px;color:#c8f05e}.objective-track,.health-track{height:4px;background:rgba(255,255,255,.18);border-radius:4px;overflow:hidden}.objective-track{margin-top:11px}.objective-track i,.health-track i{height:100%;display:block;width:0;background:#c9f45d;box-shadow:0 0 9px rgba(201,244,93,.7);transition:width .25s}.score-pill{margin:0 auto;padding:10px 15px;border-radius:6px;display:flex;align-items:center;gap:9px;font:700 14px 'Space Grotesk',sans-serif}.score-icon{color:#d8fb73;font-size:18px}.score-label{font:700 8px 'DM Sans',sans-serif;color:#9eac9f;letter-spacing:1.2px;margin-left:2px}.health-card{width:190px;padding:12px 14px;border-radius:7px}.health-head,.health-foot{display:flex;justify-content:space-between;align-items:center}.health-head{font-size:9px;letter-spacing:1.2px;font-weight:800;margin-bottom:8px}.health-head span:last-child{font:700 15px 'Space Grotesk',sans-serif;letter-spacing:0}.health-track{height:5px}.health-track i{background:linear-gradient(90deg,#ffb45c,#c9f45d)}.health-foot{margin-top:8px;font-size:8px;font-weight:800;letter-spacing:1px;color:#d9e3ce}.health-state{color:#c9f45d;font-size:7px}.ammo-card{position:absolute;top:80px;right:0;min-width:170px;padding:10px 14px;border-radius:7px;display:flex;gap:9px;align-items:center}.ammo-icon{font-size:19px;color:#d9fb76}.ammo-card b{font:700 18px 'Space Grotesk',sans-serif}.ammo-card small{font-size:11px;color:#a6b0a1}.ammo-label{font-size:8px;letter-spacing:1px;font-weight:800;color:#d6dfd1;margin-left:auto}.center-notice{position:absolute;top:42%;left:50%;transform:translate(-50%,-50%);z-index:3;text-align:center;text-shadow:0 3px 15px rgba(7,22,13,.4);pointer-events:none;transition:opacity .4s}.center-notice.hide{opacity:0}.notice-kicker{display:block;color:#dbfa81;font-weight:800;font-size:10px;letter-spacing:3px;margin-bottom:7px}.center-notice b{display:block;font:700 clamp(25px,4vw,40px) 'Space Grotesk',sans-serif;letter-spacing:-1.5px}.center-notice>span:last-child{display:block;font-size:12px;color:#edf0d8;margin-top:5px}.crosshair{position:absolute;z-index:2;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%);pointer-events:none;opacity:.82}.crosshair i{position:absolute;width:5px;height:5px;border:1px solid #fff;border-radius:50%;top:10px}.crosshair i:first-child{left:0}.crosshair i:nth-child(2){right:0}.crosshair b{position:absolute;width:3px;height:3px;background:#d8fb73;border-radius:50%;top:11px;left:11px;box-shadow:0 0 6px #d8fb73}.damage-flash{position:absolute;inset:0;pointer-events:none;z-index:3;opacity:0;background:radial-gradient(ellipse,transparent 35%,rgba(239,64,52,.52) 100%);transition:opacity .16s}.start-screen,.end-screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;padding:95px 9vw 66px;background:linear-gradient(90deg,rgba(10,25,22,.86) 0%,rgba(10,25,22,.76) 39%,rgba(10,25,22,.1) 78%,rgba(10,25,22,.02) 100%);transition:opacity .35s,visibility .35s}.start-screen.hidden,.end-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-content{width:min(440px,47vw);position:relative;z-index:2}.pretitle{display:flex;align-items:center;gap:9px;font-size:9px;font-weight:800;letter-spacing:2px;color:#d6f578}.pretitle-line{width:22px;height:1px;background:#d6f578}.start-content h1,.end-panel h2{font:700 clamp(45px,6.1vw,76px)/.91 'Space Grotesk',sans-serif;letter-spacing:-4px;margin:17px 0 15px}.start-content h1 em,.end-panel h2 em{color:#d1f36f;font-style:normal}.hero-copy{font-size:13px;line-height:1.55;color:#c1cbbd;max-width:355px;margin:0 0 21px}.class-picker{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:13px}.class-card{position:relative;text-align:left;min-width:0;height:74px;padding:9px 8px 8px 48px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.17);border-radius:6px;cursor:pointer;transition:.18s}.class-card.selected{background:rgba(205,241,108,.14);border-color:#d4f67b;box-shadow:inset 0 0 0 1px rgba(212,246,123,.12)}.class-art{position:absolute;left:9px;top:18px;width:31px;height:31px;border-radius:50%;display:grid;place-items:center;font-size:22px;background:#e6ad58;color:#fff4bb;box-shadow:0 3px 10px rgba(0,0,0,.2)}.art-thorn{background:#527d4d;color:#ddf0a2}.art-moss{background:#859a50;color:#f4d28c}.class-copy b,.class-copy small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.class-copy b{font:700 10px 'Space Grotesk',sans-serif;margin:6px 0 4px}.class-copy small{font-size:8px;color:#b5c2b2}.class-check{position:absolute;right:6px;top:5px;font-size:10px;color:#d8f67b;opacity:0}.selected .class-check{opacity:1}.play-button{width:100%;height:48px;border:0;border-radius:5px;background:#d3f36f;color:#17231b;display:flex;align-items:center;justify-content:space-between;padding:0 16px;font-size:11px;font-weight:900;letter-spacing:1.7px;cursor:pointer;box-shadow:0 8px 25px rgba(183,225,84,.2);transition:transform .15s,background .15s}.play-button:hover{transform:translateY(-2px);background:#e2ff88}.play-button b{font-size:22px;font-weight:500}.controls-note{margin-top:15px;display:flex;align-items:center;gap:9px;font-size:8px;color:#d1d9cc;font-weight:700;letter-spacing:.7px}.controls-note i{width:3px;height:3px;border-radius:50%;background:#c8ed70}.hero-aside{position:absolute;left:53%;top:50%;width:330px;height:360px;transform:translate(-3%,-43%);display:grid;place-items:center;pointer-events:none}.hero-character{width:195px;height:195px;border-radius:50%;display:grid;place-items:center;font-size:127px;color:#ffe6a1;text-shadow:0 12px 2px rgba(63,80,40,.35);background:radial-gradient(circle at 35% 25%,#fff5b8 0 7%,#f2bd61 8% 38%,#e59647 64%,#a65b38 100%);border:9px solid rgba(242,213,122,.35);box-shadow:0 0 80px rgba(218,228,104,.25),0 25px 35px rgba(12,30,17,.4);animation:bob 3s ease-in-out infinite;position:relative}.hero-character:after{content:'';position:absolute;bottom:-45px;width:96px;height:70px;border-radius:48% 48% 35% 35%;background:linear-gradient(140deg,#8cae56,#44623f);z-index:-1}.aside-orbit{position:absolute;border:1px solid rgba(214,243,120,.35);border-radius:50%;transform:rotate(-25deg)}.orbit-one{width:310px;height:115px}.orbit-two{width:350px;height:170px;transform:rotate(38deg);border-color:rgba(235,220,140,.19)}.aside-spark{position:absolute;right:33px;top:55px;color:#e0f88b;font-size:28px}.aside-label{position:absolute;bottom:0;left:calc(50% + 45px);display:flex;flex-direction:column;gap:3px;border-left:2px solid #d5f377;padding:2px 0 2px 10px;white-space:nowrap}.aside-label small{font-size:8px;letter-spacing:1.6px;color:#c6d0bb}.aside-label b{font:700 15px 'Space Grotesk',sans-serif;letter-spacing:1px}.aside-label span{font-size:7px;letter-spacing:1px;color:#c3cdbf}.start-bottom{position:absolute;bottom:25px;left:34px;right:34px;display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.4px;font-weight:700;color:rgba(240,245,222,.56)}.end-screen{justify-content:center;align-items:center;padding:24px;background:rgba(9,22,19,.58);backdrop-filter:blur(6px)}.end-panel{width:min(410px,92vw);text-align:center;padding:27px 34px 22px;border-radius:12px;background:rgba(17,34,29,.92)}.end-icon{margin:0 auto 10px;width:43px;height:43px;border-radius:50%;display:grid;place-items:center;background:rgba(209,243,111,.15);color:#d3f36f;font-size:26px}.end-panel .pretitle{justify-content:center}.end-panel h2{font-size:48px;letter-spacing:-2px;margin:13px 0 8px}.end-panel p{font-size:12px;color:#bdc8b7;margin:0 0 19px}.result-stats{display:flex;justify-content:space-around;border-block:1px solid rgba(255,255,255,.12);padding:13px 0;margin-bottom:17px}.result-stats div{display:flex;flex-direction:column;gap:3px}.result-stats b{font:700 19px 'Space Grotesk',sans-serif;color:#f2f5e8}.result-stats small{font-size:7px;letter-spacing:1px;color:#aeb9a8}.text-button{background:none;border:0;color:#b8c8a9;font-size:9px;letter-spacing:1.5px;font-weight:800;padding:13px;cursor:pointer}.toast{position:absolute;bottom:32px;left:50%;transform:translate(-50%,10px);z-index:9;padding:9px 15px;background:rgba(17,31,29,.9);border:1px solid rgba(255,255,255,.18);border-radius:20px;font-size:11px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none;position:absolute;inset:auto 0 18px;z-index:4;justify-content:space-between;align-items:flex-end;padding:0 22px;pointer-events:none}.joy-zone,.mobile-actions{pointer-events:auto}.joy-zone{width:126px;height:126px;position:relative;display:grid;place-items:center}.joy-base{width:100px;height:100px;border-radius:50%;background:rgba(12,28,24,.3);border:1px solid rgba(255,255,255,.3);box-shadow:inset 0 0 18px rgba(255,255,255,.05);display:grid;place-items:center}.joy-knob{width:43px;height:43px;border-radius:50%;background:rgba(218,244,134,.8);border:2px solid rgba(255,255,255,.65);box-shadow:0 4px 12px rgba(0,0,0,.25);transform:translate(0,0)}.joy-zone>span{position:absolute;bottom:-2px;font-size:8px;letter-spacing:1px;font-weight:800;color:rgba(255,255,255,.85)}.mobile-actions{display:flex;align-items:flex-end;gap:13px}.action-button{width:62px;height:62px;border-radius:50%;border:1px solid rgba(255,255,255,.45);background:rgba(16,35,29,.57);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;box-shadow:0 4px 15px rgba(0,0,0,.24);touch-action:none}.action-button span{font-size:24px;color:#d5f879}.action-button small{font-size:7px;letter-spacing:.8px;font-weight:800}.fire-button{width:78px;height:78px;background:rgba(199,239,94,.3);border:2px solid #dcf582}.fire-button span{font-size:30px}.special-button{margin-bottom:5px}@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
@media(max-width:760px){.topbar{height:54px;padding:0 15px}.brand{font-size:11px;letter-spacing:1.4px;gap:7px}.brand-mark{font-size:22px}.top-center{font-size:8px;letter-spacing:1px}.sound-button{padding:6px 8px;font-size:12px}.sound-button span{font-size:7px}.hud{top:64px;left:12px;right:12px}.mission-card{width:176px;padding:10px 11px}.mission-title{font-size:13px;margin:6px 0}.mission-eyebrow{font-size:7px}.mission-meta{font-size:7px}.objective-track{margin-top:8px}.score-pill{padding:8px 9px;gap:5px;margin-left:auto;margin-right:auto;font-size:11px}.score-label{font-size:7px}.health-card{position:absolute;top:62px;left:0;width:155px;padding:8px 10px}.health-head{font-size:8px;margin-bottom:5px}.health-head span:last-child{font-size:12px}.health-foot{margin-top:5px;font-size:7px}.health-state{font-size:6px}.ammo-card{top:62px;right:0;min-width:138px;padding:7px 10px;gap:6px}.ammo-card b{font-size:15px}.ammo-label{font-size:7px}.center-notice{top:43%}.start-screen{padding:74px 7vw 51px;background:linear-gradient(90deg,rgba(10,25,22,.9),rgba(10,25,22,.78) 58%,rgba(10,25,22,.35))}.start-content{width:min(430px,76vw)}.start-content h1{font-size:clamp(48px,10vw,70px)}.hero-aside{left:54%;width:250px;transform:translate(0,-47%) scale(.72);opacity:.85}.class-card{height:68px;padding-left:40px}.class-art{left:7px;width:27px;height:27px;font-size:19px}.class-copy b{font-size:9px}.class-copy small{font-size:7px}.controls-note{font-size:7px;gap:6px}.start-bottom{left:15px;right:15px;bottom:14px;font-size:7px}.mobile-controls{display:flex}.crosshair{display:none}}
@media(max-width:480px){.top-center{display:none}.start-screen{align-items:flex-start;padding:74px 20px 50px;background:linear-gradient(90deg,rgba(10,25,22,.88),rgba(10,25,22,.7) 68%,rgba(10,25,22,.3))}.start-content{width:100%;max-width:380px}.start-content h1{font-size:54px;margin-top:13px}.hero-copy{font-size:11px;max-width:290px;margin-bottom:14px}.class-picker{gap:5px;margin-bottom:10px}.class-card{height:63px;padding:5px 5px 5px 36px}.class-art{top:17px;left:5px;width:25px;height:25px;font-size:18px}.class-copy b{font-size:8px;margin-top:7px}.class-copy small{font-size:6.5px}.play-button{height:43px}.controls-note{flex-wrap:wrap;max-width:320px;margin-top:11px;font-size:7px}.hero-aside{left:34%;top:56%;transform:translate(0,-40%) scale(.58);opacity:.32}.aside-label{display:none}.mission-card{width:150px}.mission-title{font-size:12px}.score-pill{position:absolute;top:0;right:0}.health-card{top:59px;width:142px}.ammo-card{top:59px;min-width:125px}.health-foot{font-size:6px}.mobile-controls{padding:0 12px;bottom:13px}.joy-zone{transform:scale(.88);transform-origin:bottom left}.mobile-actions{gap:8px}.action-button{width:53px;height:53px}.fire-button{width:68px;height:68px}.special-button{margin-bottom:2px}.end-panel{padding:22px 22px 16px}.end-panel h2{font-size:43px}}
@media(max-height:520px){.start-screen{padding-top:62px;padding-bottom:38px}.start-content h1{font-size:45px;margin:9px 0}.hero-copy{margin-bottom:10px;font-size:11px}.class-card{height:58px}.play-button{height:39px}.controls-note{margin-top:8px}.hero-aside{transform:translate(0,-43%) scale(.65)}.hud{top:62px}.mobile-controls{bottom:4px}.joy-zone{transform:scale(.72);transform-origin:bottom left}.mobile-actions{transform:scale(.78);transform-origin:bottom right}.start-bottom{bottom:8px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { start:$('start-screen'), end:$('end-screen'), hud:$('hud'), notice:$('center-notice'), joy:$('joy-zone'), knob:$('joy-knob'), fire:$('fire-button'), special:$('special-button') };
  const classes = {
    sunbloom:{name:'Sunbloom',hp:100,speed:210,damage:24,rate:.27,ammo:12,color:'#f4b655',shot:'#d7ef64',special:'Solar flare'},
    thorn:{name:'Thornshot',hp:78,speed:250,damage:40,rate:.48,ammo:8,color:'#84ad68',shot:'#abdf6b',special:'Bramble dash'},
    moss:{name:'Mossback',hp:145,speed:165,damage:17,rate:.17,ammo:18,color:'#a2a758',shot:'#f2d074',special:'Spore shield'}
  };
  const W=1200,H=820, TAU=Math.PI*2;
  let dpr=1, viewW=0,viewH=0, chosen='sunbloom',state='menu',last=0, elapsed=0, noticeTimer=0, toastTimer=0;
  let game={player:null,enemies:[],shots:[],enemyShots:[],particles:[],decor:[],wave:1,score:0,kills:0,spawned:0,total:0,spawnClock:0,breakTimer:0,ammo:12,reload:0,fireClock:0,special:0,specialClock:0,shake:0,aim:{x:1,y:0},joystick:{x:0,y:0},keys:{},fireHeld:false,muted:false};
  function resize(){dpr=Math.min(window.devicePixelRatio||1,2);viewW=innerWidth;viewH=innerHeight;canvas.width=Math.floor(viewW*dpr);canvas.height=Math.floor(viewH*dpr);canvas.style.width=viewW+'px';canvas.style.height=viewH+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize); resize();
  function rand(a,b){return a+Math.random()*(b-a)}
  function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
  function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
  function choose(arr){return arr[Math.floor(Math.random()*arr.length)]}
  function makeDecor(){game.decor=[];for(let i=0;i<48;i++){let x=rand(45,W-45),y=rand(55,H-55);if(Math.hypot(x-W/2,y-H/2)<185)continue;game.decor.push({x,y,type:Math.random()<.54?'flower':'rock',s:rand(.55,1.3),h:rand(0,TAU)})}}
  function setupGame(){const c=classes[chosen];game={player:{x:W/2,y:H/2,hp:c.hp,maxHp:c.hp,angle:0,invuln:0,slow:0},enemies:[],shots:[],enemyShots:[],particles:[],decor:game.decor,wave:1,score:0,kills:0,spawned:0,total:7,spawnClock:1.6,breakTimer:0,ammo:c.ammo,reload:0,fireClock:0,special:1,specialClock:0,shake:0,aim:{x:1,y:0},joystick:{x:0,y:0},keys:{},fireHeld:false,muted:game.muted};ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.hud.style.display='flex';$('top-status').textContent='SECTOR 07 / ACTIVE';$('class-name-hud').textContent=c.name.toUpperCase();$('center-notice').classList.remove('hide');$('center-notice').querySelector('.notice-kicker').textContent='WAVE INCOMING';$('center-notice').querySelector('b').textContent='Hold the garden!';$('center-notice').querySelector('span:last-child').textContent='Get ready, sprout.';noticeTimer=2.1;state='playing';updateHud();}
  function showToast(message){const t=$('toast');t.textContent=message;t.classList.add('show');toastTimer=1.6}
  function hideNotice(){ui.notice.classList.add('hide')}
  function startWave(){const total=[7,10,13][game.wave-1];game.total=total;game.spawned=0;game.spawnClock=.55;game.breakTimer=0;$('wave-label').textContent=`WAVE ${game.wave} / 3`;ui.notice.querySelector('.notice-kicker').textContent=`WAVE ${game.wave} INCOMING`;ui.notice.querySelector('b').textContent=game.wave===1?'Here they come!':game.wave===2?'More are crawling in!':'Final wave!';ui.notice.querySelector('span:last-child').textContent='Keep the lawn under control.';ui.notice.classList.remove('hide');noticeTimer=1.4}
  function spawnEnemy(){let side=Math.floor(Math.random()*4),x=side===0?-25:side===1?W+25:rand(0,W),y=side===2?-25:side===3?H+25:rand(0,H);let type=Math.random()<.23?'runner':Math.random()<.28?'brute':'walker';let base={walker:{hp:58,speed:48,damage:11,r:20,color:'#8d9f70',score:100},runner:{hp:38,speed:86,damage:8,r:15,color:'#d18c56',score:140},brute:{hp:145,speed:31,damage:19,r:27,color:'#777d58',score:240}}[type];game.enemies.push({x,y,type,hp:base.hp,maxHp:base.hp,speed:base.speed*(1+game.wave*.08),damage:base.damage,r:base.r,color:base.color,score:base.score,angle:0,attack:rand(.1,1),stun:0,wobble:rand(0,TAU),hit:0});}
  function resetToMenu(){state='menu';ui.end.classList.add('hidden');ui.start.classList.remove('hidden');ui.hud.style.display='none';$('top-status').textContent='TRAINING GROUNDS'}
  function endGame(win){state=win?'won':'lost';$('end-kicker').textContent=win?'MISSION COMPLETE':'SQUAD DOWN';$('end-title').innerHTML=win?'LAWN<br><em>SAVED.</em>':'BACK TO<br><em>THE ROOTS.</em>';$('end-copy').textContent=win?'The garden is looking greener already.':'A little water, a little rest. Ready for another round?';$('end-icon').textContent=win?'✿':'↻';$('final-score').textContent=String(game.score).padStart(4,'0');$('final-kills').textContent=String(game.kills).padStart(2,'0');$('final-wave').textContent=String(win?3:game.wave-1).padStart(2,'0');ui.end.classList.remove('hidden');}
