  function drawHero(p,angle){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(angle);ctx.fillStyle='rgba(29,53,27,.28)';ctx.beginPath();ctx.ellipse(-2,10,24,12,0,0,TAU);ctx.fill();if(p.invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.48;
