    // sunflower head and petals
    let petal=chosen==='thorn'?'#92bc6e':chosen==='moss'?'#c5b85e':'#f3bf5b',center=chosen==='thorn'?'#8a633e':'#845338';for(let i=0;i<9;i++){let a=i*TAU/9;ctx.fillStyle=petal;ctx.beginPath();ctx.ellipse(20+Math.cos(a)*11,Math.sin(a)*11,8,5,a,0,TAU);ctx.fill()}ctx.fillStyle=center;ctx.beginPath();ctx.arc(20,0,9,0,TAU);ctx.fill();ctx.fillStyle='#fff4c8';ctx.beginPath();ctx.ellipse(22,-3,2,2,0,0,TAU);ctx.ellipse(22,3,2,2,0,0,TAU);ctx.fill();ctx.fillStyle='#46362d';ctx.beginPath();ctx.arc(22,-3,1,0,TAU);ctx.arc(22,3,1,0,TAU);ctx.fill();
    // seed blaster
    ctx.fillStyle='#344639';rounded(18,9,24,10,4);ctx.fill();ctx.fillStyle='#c8e775';rounded(35,10,11,7,3);ctx.fill();ctx.fillStyle='#24342b';rounded(24,16,8,8,2);ctx.fill();ctx.restore();}
  function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y+Math.sin(e.wobble)*2);ctx.rotate(e.angle);let s=e.type==='brute'?1.3:e.type==='runner'?.78:1;ctx.scale(s,s);ctx.fillStyle='rgba(38,43,27,.28)';ctx.beginPath();ctx.ellipse(-2,14,23,11,0,0,TAU);ctx.fill();
